create function touch_updated() returns trigger language plpgsql as $$ begin new.updated_at=now(); return new; end $$;
create table subsidiaries(id uuid primary key default gen_random_uuid(), external_id text unique, name text not null unique, country text not null check(country in ('NZ','AU')), currency text not null check(currency in ('NZD','AUD')), tax_year_end date not null, created_at timestamptz not null default now(), updated_at timestamptz not null default now());
create table partners(id uuid primary key default gen_random_uuid(), external_id text unique, name text not null, kind text not null check(kind in ('customer','vendor')), created_at timestamptz not null default now(), updated_at timestamptz not null default now());
create table items(id uuid primary key default gen_random_uuid(), external_id text unique, name text not null unique, unit text not null default 'each', created_at timestamptz not null default now(), updated_at timestamptz not null default now());
create table locations(id uuid primary key default gen_random_uuid(), external_id text unique, name text not null unique, subsidiary_id uuid not null references subsidiaries, created_at timestamptz not null default now(), updated_at timestamptz not null default now(), unique(id,subsidiary_id));
create table orders(id uuid primary key default gen_random_uuid(), external_id text unique, name text not null unique, subsidiary_id uuid not null references subsidiaries, location_id uuid not null, partner_id uuid not null references partners, kind text not null check(kind in ('sale','purchase')), currency text not null check(currency in ('NZD','AUD')), due_date date not null, status text not null default 'draft' check(status in ('draft','open','closed','cancelled')), last_contact date, created_at timestamptz not null default now(), updated_at timestamptz not null default now(), foreign key(location_id,subsidiary_id) references locations(id,subsidiary_id));
create table order_lines(id uuid primary key default gen_random_uuid(), external_id text unique, order_id uuid not null references orders, item_id uuid not null references items, quantity numeric(14,3) not null check(quantity>0), completed numeric(14,3) not null default 0 check(completed>=0 and completed<=quantity), unit_price numeric(14,2) not null check(unit_price>=0), unit_cost numeric(14,2) not null check(unit_cost>=0), created_at timestamptz not null default now(), updated_at timestamptz not null default now());
create table stock(id uuid primary key default gen_random_uuid(), location_id uuid not null references locations, item_id uuid not null references items, quantity numeric(14,3) not null default 0 check(quantity>=0), reorder_point numeric(14,3) not null default 0 check(reorder_point>=0), created_at timestamptz not null default now(), updated_at timestamptz not null default now(), unique(location_id,item_id));
create table movements(id uuid primary key default gen_random_uuid(), name text not null unique, location_id uuid not null references locations, item_id uuid not null references items, line_id uuid references order_lines, quantity numeric(14,3) not null check(quantity<>0), reason text not null, created_at timestamptz not null default now(), updated_at timestamptz not null default now());
create table followups(id uuid primary key default gen_random_uuid(), order_id uuid not null references orders, note text not null, created_at timestamptz not null default now(), updated_at timestamptz not null default now());
create table intercompany(id uuid primary key default gen_random_uuid(), external_id text unique, name text not null, subsidiary_id uuid not null references subsidiaries, counterparty_id uuid not null references subsidiaries, side text not null check(side in ('receivable','payable')), currency text not null check(currency in ('NZD','AUD')), amount numeric(14,2) not null check(amount>=0), due_date date not null, evidence text not null default '', created_at timestamptz not null default now(), updated_at timestamptz not null default now(), check(subsidiary_id<>counterparty_id), unique(name,subsidiary_id,side));
create table fx_rates(id uuid primary key default gen_random_uuid(), currency text not null check(currency in ('NZD','AUD')), rate_date date not null, nzd_per_unit numeric(14,6) not null check(nzd_per_unit>0), source text not null check(length(source)>0), created_at timestamptz not null default now(), updated_at timestamptz not null default now(), unique(currency,rate_date));
create table evidence(id uuid primary key default gen_random_uuid(), external_id text unique, name text not null, subsidiary_id uuid not null references subsidiaries, period_end date not null, retain_until date not null, archive_ref text not null default '', last_backup date, created_at timestamptz not null default now(), updated_at timestamptz not null default now());
create table audit(id uuid primary key default gen_random_uuid(), action text not null, detail jsonb not null, created_at timestamptz not null default now(), updated_at timestamptz not null default now());
do $$ declare t text; begin foreach t in array array['subsidiaries','partners','items','locations','orders','order_lines','stock','movements','followups','intercompany','fx_rates','evidence','audit'] loop execute format('create trigger touch before update on %I for each row execute function touch_updated()',t); end loop; end $$;
create view v_orders as select o.id,o.name,s.name subsidiary,o.kind,p.name partner,o.currency,o.due_date,o.status,o.last_contact,coalesce(sum(l.quantity*l.unit_price),0)::numeric(16,2) value,coalesce(sum((l.quantity-l.completed)*l.unit_price),0)::numeric(16,2) remaining_value,coalesce(sum(l.quantity-l.completed),0)::numeric(16,3) remaining_units from orders o join subsidiaries s on s.id=o.subsidiary_id join partners p on p.id=o.partner_id left join order_lines l on l.order_id=o.id group by o.id,s.name,p.name;
create view v_dispatch as select l.id line_id,o.name order_name,s.name subsidiary,w.name location,i.name item,o.currency,o.due_date,(l.quantity-l.completed) remaining,coalesce(k.quantity,0) on_hand,greatest(l.quantity-l.completed-coalesce(k.quantity,0),0) shortage from order_lines l join orders o on o.id=l.order_id join subsidiaries s on s.id=o.subsidiary_id join locations w on w.id=o.location_id join items i on i.id=l.item_id left join stock k on k.location_id=o.location_id and k.item_id=l.item_id where o.kind='sale' and o.status='open' and l.completed<l.quantity;
create view v_stock as select k.id,s.name subsidiary,w.name location,i.name item,k.quantity,k.reorder_point,coalesce((select sum(l.quantity-l.completed) from order_lines l join orders o on o.id=l.order_id where o.location_id=k.location_id and l.item_id=k.item_id and o.kind='sale' and o.status='open'),0) committed,coalesce((select sum(l.quantity-l.completed) from order_lines l join orders o on o.id=l.order_id where o.location_id=k.location_id and l.item_id=k.item_id and o.kind='purchase' and o.status='open'),0) incoming from stock k join locations w on w.id=k.location_id join subsidiaries s on s.id=w.subsidiary_id join items i on i.id=k.item_id;
create view v_intercompany as select coalesce(r.name,p.name) reference,coalesce(r.currency,p.currency) currency,rs.name seller,ps.name buyer,r.amount receivable,p.amount payable,coalesce(r.amount,0)-coalesce(p.amount,0) difference,case when r.id is null or p.id is null then 'missing counterpart' when r.amount<>p.amount then 'amount mismatch' when r.evidence='' or p.evidence='' then 'missing evidence' else 'matched' end status from (select * from intercompany where side='receivable') r full join (select * from intercompany where side='payable') p on r.name=p.name and r.currency=p.currency and r.subsidiary_id=p.counterparty_id and r.counterparty_id=p.subsidiary_id left join subsidiaries rs on rs.id=coalesce(r.subsidiary_id,p.counterparty_id) left join subsidiaries ps on ps.id=coalesce(p.subsidiary_id,r.counterparty_id);
